// src/components/KnowYourCandidate.js
import React, { useState } from 'react';
import { GoogleGenerativeAI } from '@google/generative-ai';

const KnowYourCandidate = ({ user, language }) => {
  const [candidateInfo, setCandidateInfo] = useState(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  const [searchQuery, setSearchQuery] = useState('');
  const [constituency, setConstituency] = useState(user?.constituency || '');
  const [usingFallback, setUsingFallback] = useState(false);

  // Initialize Gemini AI
  const genAI = new GoogleGenerativeAI('AIzaSyDAg9-I7KPUQFnLxV0d_Cy8KM44CEm6WdE');

  const fetchCandidateInfo = async () => {
    if (!constituency) {
      setError(language === 'hindi' 
        ? 'कृपया पहले अपना निर्वाचन क्षेत्र सेट करें' 
        : 'Please set your constituency first'
      );
      return;
    }

    setLoading(true);
    setError('');
    setCandidateInfo(null);
    setUsingFallback(false);

    try {
      console.log('Attempting to fetch AI data for:', constituency);
      
      // Try Gemini AI first
      const model = genAI.getGenerativeModel({ model: "gemini-pro" });
      
      const prompt = `
        Provide 2024 Lok Sabha election candidates for ${constituency} constituency.
        Return as JSON array with: name, party, education, experience, promises array, contact.
        Use Hindi and English both.
        Example format:
        [
          {
            "name": "नाम हिंदी / Name English",
            "party": "पार्टी हिंदी / Party English",
            "education": "शिक्षा हिंदी / Education English",
            "experience": "अनुभव हिंदी / Experience English",
            "promises": ["वादा 1 / Promise 1", "वादा 2 / Promise 2"],
            "contact": "contact@example.com"
          }
        ]
      `;

      const result = await model.generateContent(prompt);
      const response = await result.response;
      const text = response.text();
      
      console.log('AI Response received');
      
      let cleanedText = text.replace(/```json|```/g, '').trim();
      const jsonMatch = cleanedText.match(/\[[\s\S]*\]/);
      if (jsonMatch) {
        cleanedText = jsonMatch[0];
      }
      
      const candidates = JSON.parse(cleanedText);
      setCandidateInfo(candidates);
      setLoading(false);
      
    } catch (aiError) {
      console.log('AI failed, using fallback data:', aiError);
      setUsingFallback(true);
      
      // Use comprehensive fallback data
      const fallbackCandidates = getComprehensiveFallbackData(constituency);
      setCandidateInfo(fallbackCandidates);
      
      setError(language === 'hindi' 
        ? 'लाइव डेटा लोड नहीं हो सका। स्टोरेज डेटा दिखाया जा रहा है' 
        : 'Live data unavailable. Showing stored data'
      );
      setLoading(false);
    }
  };

  // Comprehensive fallback data for major constituencies
  const getComprehensiveFallbackData = (constituency) => {
    const fallbackData = {
      'Pune': [
        {
          name: 'मुरलीधर मोहोल / Murlidhar Mohol',
          party: 'भारतीय जनता पार्टी / BJP',
          education: 'बैचलर ऑफ आर्ट्स, पुणे विश्वविद्यालय / Bachelor of Arts, Pune University',
          experience: 'पूर्व महापौर पुणे, नगर निगम अध्यक्ष / Former Mayor of Pune, Municipal Corporation Chairman',
          promises: [
            'पुणे मेट्रो का तेजी से निर्माण / Accelerated Pune Metro construction',
            'यातायात जाम समस्या का समाधान / Traffic congestion solutions',
            'स्मार्ट सिटी विकास और डिजिटल इन्फ्रास्ट्रक्चर / Smart city development and digital infrastructure',
            'युवाओं के लिए स्टार्टअप इकोसिस्टम / Startup ecosystem for youth'
          ],
          contact: 'mohol.bjp@example.com | Twitter: @moholbjp'
        },
        {
          name: 'रविन्द्र दरदे / Ravindra Dardhe',
          party: 'शिव सेना / Shiv Sena',
          education: 'एम.ए. राजनीति विज्ञान, सावित्रीबाई फुले पुणे विश्वविद्यालय / MA Political Science, SPPU',
          experience: 'विधान सभा सदस्य, जिला परिषद अध्यक्ष / MLA, District Council Chairman',
          promises: [
            'मराठी अस्मिता और संस्कृति की रक्षा / Protect Marathi identity and culture',
            'स्थानीय युवाओं के लिए रोजगार के अवसर / Employment opportunities for local youth',
            'नगर निगम सुधार और पारदर्शिता / Municipal corporation reforms and transparency',
            'किसानों के लिए बेहतर मूल्य सहायता / Better price support for farmers'
          ],
          contact: 'shivsena.pune@example.com | Twitter: @shivsenapune'
        }
      ],
      'Varanasi': [
        {
          name: 'नरेंद्र मोदी / Narendra Modi',
          party: 'भारतीय जनता पार्टी / BJP',
          education: 'दिल्ली विश्वविद्यालय (बी.ए.), गुजरात विश्वविद्यालय (एम.ए.) / Delhi University (BA), Gujarat University (MA)',
          experience: 'भारत के प्रधानमंत्री, गुजरात के पूर्व मुख्यमंत्री / Prime Minister of India, Former CM of Gujarat',
          promises: [
            'विकास कार्यों को जारी रखना और गति देना / Continue and accelerate development works',
            'काशी विश्वनाथ धाम और धार्मिक पर्यटन को बढ़ावा / Promote Kashi Vishwanath Dham and religious tourism',
            'गंगा स्वच्छता अभियान को मजबूत करना / Strengthen Ganga cleanliness campaign',
            'पारंपरिक उद्योगों और हस्तशिल्प को समर्थन / Support traditional industries and handicrafts'
          ],
          contact: 'pmindia@example.com | Twitter: @narendramodi'
        },
        {
          name: 'अजय राय / Ajay Rai',
          party: 'भारतीय राष्ट्रीय कांग्रेस / Indian National Congress',
          education: 'स्नातक, वाराणसी विश्वविद्यालय / Graduate, Banaras Hindu University',
          experience: 'विधायक, प्रदेश कांग्रेस समिति सदस्य / MLA, State Congress Committee Member',
          promises: [
            'युवाओं के लिए रोजगार और स्वरोजगार के अवसर / Employment and self-employment opportunities for youth',
            'किसानों की आय दोगुनी करने का लक्ष्य / Target to double farmers income',
            'महिला सशक्तिकरण और सुरक्षा / Women empowerment and safety',
            'सस्ती और गुणवत्तापूर्ण स्वास्थ्य सेवा / Affordable and quality healthcare'
          ],
          contact: 'congress.varanasi@example.com | Twitter: @congressvaranasi'
        }
      ],
      'Amethi': [
        {
          name: 'राहुल गांधी / Rahul Gandhi',
          party: 'भारतीय राष्ट्रीय कांग्रेस / Indian National Congress',
          education: 'हार्वर्ड विश्वविद्यालय, रोलिन्स कॉलेज / Harvard University, Rollins College',
          experience: 'सांसद वायनाड, पूर्व कांग्रेस अध्यक्ष / MP Wayanad, Former Congress President',
          promises: [
            'न्यूनतम आय गारंटी योजना (न्याय) / Minimum Income Guarantee Scheme (NYAY)',
            'किसानों के लिए ऋण माफी और बेहतर MSP / Loan waiver and better MSP for farmers',
            'सरकारी नौकरियों में भर्ती बढ़ाना / Increase government job recruitment',
            'महिलाओं के लिए 33% आरक्षण / 33% reservation for women'
          ],
          contact: 'inc.amethi@example.com | Twitter: @RahulGandhi'
        },
        {
          name: 'स्मृति ईरानी / Smriti Irani',
          party: 'भारतीय जनता पार्टी / BJP',
          education: 'दिल्ली विश्वविद्यालय (स्नातक) / Delhi University (Graduate)',
          experience: 'केंद्रीय मंत्री, सांसद अमेठी / Central Minister, MP Amethi',
          promises: [
            'विकास कार्यों को गति देना / Accelerate development works',
            'महिला सशक्तिकरण और बेटी बचाओ बेटी पढ़ाओ / Women empowerment and Beti Bachao Beti Padhao',
            'युवाओं के लिए रोजगार और कौशल विकास / Employment and skill development for youth',
            'किसानों के लिए सिंचाई सुविधाएं बढ़ाना / Increase irrigation facilities for farmers'
          ],
          contact: 'bjp.amethi@example.com | Twitter: @smritiirani'
        }
      ],
      'default': [
        {
          name: 'मुख्य उम्मीदवार / Main Candidate',
          party: 'राष्ट्रीय पार्टी / National Party',
          education: 'स्नातक / Graduate',
          experience: 'स्थानीय नेता, सामाजिक कार्यकर्ता / Local Leader, Social Worker',
          promises: [
            'विकास कार्य और बुनियादी ढांचा / Development works and infrastructure',
            'रोजगार के अवसर और युवा रोजगार / Employment opportunities and youth employment',
            'शिक्षा और स्वास्थ्य सुविधाएं / Education and health facilities',
            'किसान कल्याण और कृषि विकास / Farmer welfare and agricultural development'
          ],
          contact: 'candidate@example.com'
        },
        {
          name: 'प्रतिद्वंद्वी उम्मीदवार / Opponent Candidate',
          party: 'क्षेत्रीय पार्टी / Regional Party',
          education: 'स्नातकोत्तर / Post Graduate',
          experience: 'पूर्व विधायक, पार्टी पदाधिकारी / Former MLA, Party Office Bearer',
          promises: [
            'स्थानीय मुद्दों का समाधान / Solve local issues',
            'महिला सुरक्षा और सशक्तिकरण / Women safety and empowerment',
            'स्वच्छता और पर्यावरण संरक्षण / Cleanliness and environment protection',
            'पारदर्शी शासन और जनभागीदारी / Transparent governance and public participation'
          ],
          contact: 'opponent@example.com'
        }
      ]
    };

    return fallbackData[constituency] || fallbackData.default;
  };

  const handleSearch = (e) => {
    e.preventDefault();
    if (constituency) {
      fetchCandidateInfo();
    }
  };

  const handleConstituencySelect = (e) => {
    setConstituency(e.target.value);
    setError('');
    setCandidateInfo(null);
    setUsingFallback(false);
  };

  const handleKeyPress = (e) => {
    if (e.key === 'Enter' && constituency) {
      fetchCandidateInfo();
    }
  };

  const translations = {
    hindi: {
      title: "अपने उम्मीदवार को जानें",
      searchPlaceholder: "उम्मीदवार का नाम या पार्टी खोजें...",
      searchButton: "खोजें",
      selectConstituency: "अपना निर्वाचन क्षेत्र चुनें",
      constituency: "आपका निर्वाचन क्षेत्र",
      fetchButton: "उम्मीदवार जानकारी प्राप्त करें",
      loading: "जानकारी लोड हो रही है...",
      candidateInfo: "उम्मीदवार की जानकारी",
      name: "नाम",
      party: "पार्टी",
      education: "शिक्षा",
      experience: "राजनीतिक अनुभव",
      promises: "वादे और घोषणापत्र",
      contact: "संपर्क",
      noConstituency: "कृपया पहले अपना निर्वाचन क्षेत्र सेट करें",
      aiPowered: "यह जानकारी Google Gemini AI द्वारा प्रदान की गई है",
      storedData: "संग्रहीत जानकारी दिखाई जा रही है",
      noCandidates: "कोई उम्मीदवार नहीं मिले",
      liveData: "लाइव डेटा लोड हो रहा है...",
      searchResults: "खोज परिणाम",
      realTimeInfo: "रियल-टाइम जानकारी"
    },
    english: {
      title: "Know Your Candidate",
      searchPlaceholder: "Search candidate name or party...",
      searchButton: "Search",
      selectConstituency: "Select Your Constituency",
      constituency: "Your Constituency",
      fetchButton: "Get Candidate Info",
      loading: "Loading information...",
      candidateInfo: "Candidate Information",
      name: "Name",
      party: "Party",
      education: "Education",
      experience: "Political Experience",
      promises: "Promises & Manifesto",
      contact: "Contact",
      noConstituency: "Please set your constituency first",
      aiPowered: "This information is provided by Google Gemini AI",
      storedData: "Showing stored information",
      noCandidates: "No candidates found",
      liveData: "Loading live data...",
      searchResults: "Search Results",
      realTimeInfo: "Real-time Information"
    }
  };

  const t = translations[language];

  const constituencies = [
    "Amethi", "Rae Bareli", "Varanasi", "Lucknow", "Kanpur", 
    "Ghaziabad", "Allahabad", "Gorakhpur", "Agra", "Meerut",
    "Delhi South", "Mumbai North", "Bangalore South", "Chennai Central", 
    "Hyderabad", "Kolkata North", "Ahmedabad East", "Pune", "Jaipur", "Chandigarh"
  ];
      {constituency ? (
        <div className="constituency-info">
          <div className="info-card">
            <h4>🎯 {t.constituency}</h4>
            <p className="constituency-name">{constituency}</p>
            <div className="real-time-badge">
              <span className="live-dot"></span>
              {usingFallback ? t.storedData : t.realTimeInfo}
            </div>
          </div>
        </div>
      ) : (
        <div className="warning-message">
          <div className="warning-icon">⚠️</div>
          <div>
            <h4>{t.noConstituency}</h4>
          </div>
        </div>
      )}

      <div className="action-section">
        <button 
          onClick={fetchCandidateInfo} 
          className="fetch-button"
          disabled={loading || !constituency}
        >
          {loading ? (
            <div className="button-loading">
              <span className="spinner"></span>
              {t.loading}
            </div>
          ) : (
            t.fetchButton
          )}
        </button>
      </div>

      {error && (
        <div className="error-message">
          <div className="error-icon">⚠️</div>
          <p>{error}</p>
        </div>
      )}

      {candidateInfo && (
        <div className="candidates-list">
          <div className="ai-notice">
            <div className="ai-icon">✨</div>
            <div>
              <p><strong>{usingFallback ? t.storedData : t.aiPowered}</strong></p>
              <small>{constituency} - {new Date().toLocaleDateString()}</small>
            </div>
          </div>
          
          <h3>
            {t.candidateInfo} - {constituency}
            {searchQuery && (
              <span className="search-results-badge"> ({t.searchResults}: "{searchQuery}")</span>
            )}
          </h3>
          
          {candidateInfo.length === 0 ? (
            <div className="no-candidates">
              <p>{t.noCandidates}</p>
            </div>
          ) : (
            <div className="candidates-grid">
              {candidateInfo.map((candidate, index) => (
                <div key={index} className="candidate-card">
                  <div className="candidate-header-card">
                    <div className="candidate-avatar">
                      {candidate.name.charAt(0)}
                    </div>
                    <div className="candidate-basic-info">
                      <h4>{candidate.name}</h4>
                      <span className="party-badge">{candidate.party}</span>
                    </div>
                  </div>
                  
                  <div className="candidate-details">
                    <div className="detail-item">
                      <span className="detail-label">🎓 {t.education}:</span>
                      <span className="detail-value">{candidate.education}</span>
                    </div>
                    
                    <div className="detail-item">
                      <span className="detail-label">💼 {t.experience}:</span>
                      <span className="detail-value">{candidate.experience}</span>
                    </div>
                    
                    {candidate.contact && (
                      <div className="detail-item">
                        <span className="detail-label">📞 {t.contact}:</span>
                        <span className="detail-value">{candidate.contact}</span>
                      </div>
                    )}
                  </div>

                  <div className="promises-section">
                    <h5>📋 {t.promises}:</h5>
                    <ul className="promises-list">
                      {candidate.promises && candidate.promises.map((promise, promiseIndex) => (
                        <li key={promiseIndex} className="promise-item">
                          <span className="promise-icon">✓</span>
                          {promise}
                        </li>
                      ))}
                    </ul>
                  </div>
                </div>
              ))}
            </div>
          )}
        </div>
      )}
      
};

export default KnowYourCandidate;
